#include <cstdio>
#include <algorithm>

using namespace std;

long long dp(long long n, long long m) {
    if (n <= 0 || m <= 0) return 0;

    long long low = 0;
    long long high = (n + m - 2) / 3;
    long long best = 0;

    while (low <= high) {
        long long moves = low + (high - low) / 2;
        long long minTypeOne = max(0LL, 2 * moves - n + 1);
        long long maxTypeOne = min(moves, m - 1 - moves);

        if (minTypeOne <= maxTypeOne) {
            best = moves;
            low = moves + 1;
        } else {
            high = moves - 1;
        }
    }

    return best + 1;
}

int main() {
    long long ex, ne;
    while (scanf("%lld%lld", &ex, &ne) == 2) {
        printf("%lld\n", dp(ex, ne));
    }
    return 0;
}

